-- V2 par levels: configuration only. Does not change inventory, Shopify, or Qoblex.
create table if not exists public.location_category_par_levels (id bigint generated by default as identity primary key,location_id bigint not null references public.locations(id) on delete cascade,category text not null check(length(btrim(category))>0),par_quantity numeric not null check(par_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(location_id,category));
create table if not exists public.product_par_levels (id bigint generated by default as identity primary key,location_id bigint not null references public.locations(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,par_quantity numeric not null check(par_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(location_id,product_id));
create index if not exists location_category_par_levels_location_category_idx on public.location_category_par_levels(location_id,category);
create index if not exists product_par_levels_location_product_idx on public.product_par_levels(location_id,product_id);
alter table public.location_category_par_levels enable row level security;
alter table public.product_par_levels enable row level security;
create or replace function public.save_v2_category_par_level(p_location_id bigint,p_category text,p_par_quantity numeric,p_user_id uuid,p_user_name text) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $ declare v_name text; v_category text:=btrim(p_category); begin if p_par_quantity is null or p_par_quantity<0 then raise exception 'Par quantity must be zero or greater'; end if; select name into v_name from public.locations where id=p_location_id and active=true;if v_name is null then raise exception 'Active location not found';end if;if v_category='' then raise exception 'Category is required';end if;insert into public.location_category_par_levels(location_id,category,par_quantity,updated_at) values(p_location_id,v_category,p_par_quantity,now()) on conflict(location_id,category) do update set par_quantity=excluded.par_quantity,updated_at=now();insert into public.activity_events(action,entity_type,entity_id,status,description,performed_by_user_id,performed_by_name,metadata) values('PAR_LEVEL_CONFIGURED','location_category_par',p_location_id::text,'success','Set category par for '||v_category||' at '||v_name,p_user_id,p_user_name,jsonb_build_object('location_id',p_location_id,'category',v_category,'par_quantity',p_par_quantity));return jsonb_build_object('ok',true);end $;
create or replace function public.save_v2_product_par_level(p_location_id bigint,p_product_id bigint,p_par_quantity numeric,p_user_id uuid,p_user_name text) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $ declare v_name text; v_sku text; begin if p_par_quantity is null or p_par_quantity<0 then raise exception 'Par quantity must be zero or greater';end if;select name into v_name from public.locations where id=p_location_id and active=true;if v_name is null then raise exception 'Active location not found';end if;select sku into v_sku from public.products where id=p_product_id;if v_sku is null then raise exception 'Product not found';end if;insert into public.product_par_levels(location_id,product_id,par_quantity,updated_at) values(p_location_id,p_product_id,p_par_quantity,now()) on conflict(location_id,product_id) do update set par_quantity=excluded.par_quantity,updated_at=now();insert into public.activity_events(action,entity_type,entity_id,status,description,performed_by_user_id,performed_by_name,metadata) values('PAR_LEVEL_CONFIGURED','product_par',p_product_id::text,'success','Set SKU par for '||v_sku||' at '||v_name,p_user_id,p_user_name,jsonb_build_object('location_id',p_location_id,'product_id',p_product_id,'sku',v_sku,'par_quantity',p_par_quantity));return jsonb_build_object('ok',true);end $;
revoke all on function public.save_v2_category_par_level(bigint,text,numeric,uuid,text) from public,anon,authenticated;
revoke all on function public.save_v2_product_par_level(bigint,bigint,numeric,uuid,text) from public,anon,authenticated;
grant execute on function public.save_v2_category_par_level(bigint,text,numeric,uuid,text) to service_role;
grant execute on function public.save_v2_product_par_level(bigint,bigint,numeric,uuid,text) to service_role;
revoke all on table public.location_category_par_levels,public.product_par_levels from anon,authenticated;